215			if r, ok := right.(string); ok {
216				switch op {
217				case CompareEq:
218					return l == r, nil
219				case CompareNeq:
220					return l != r, nil
221				case CompareLt:
222					return l < r, nil
223				case CompareLte:
224					return l <= r, nil
225				case CompareGt:
226					return l > r, nil
227				case CompareGte:
228					return l >= r, nil
229				}
230			}
231		}
232		if l, ok := left.(bool); ok {
233			if r, ok := right.(bool); ok {
234				switch op {
235				case CompareEq:
236					return l == r, nil
237				case CompareNeq:
238					return l != r, nil
239				}
240			}
241		}
242		return false, errors.Errorf("unsupported constant comparison %T %s %T", left, op, right)
243	}
