894	func toInt64(value any) (int64, error) {
895		switch v := value.(type) {
896		case int:
897			return int64(v), nil
898		case int32:
899			return int64(v), nil
900		case int64:
901			return v, nil
902		case uint32:
903			return int64(v), nil
904		case uint64:
905			return int64(v), nil
906		case float32:
907			return int64(v), nil
908		case float64:
909			return int64(v), nil
910		default:
911			return 0, errors.Errorf("cannot convert %T to int64", value)
912		}
913	}
