919	func qualifyColumn(d DialectName, col Column) string {
920		switch d {
921		case DialectPostgres:
922			return fmt.Sprintf("%s.%s", col.Table, col.Name)
923		default:
924			return fmt.Sprintf("`%s`.`%s`", col.Table, col.Name)
925		}
926	}
